struct lwan_strbuf {
    union {
        char *buffer;
        const char *static_buffer;
    } value;
    size_t used;
    unsigned int flags;
};

static inline bool lwan_strbuf_init(struct lwan_strbuf *buf) {
    buf->value.buffer = NULL;
    buf->used = 0;
    buf->flags = 0;
