static inline bool lwan_strbuf_append_str(struct lwan_strbuf *s1, const char *s2, size_t sz) { return true; }
#define lwan_strbuf_get_length(s) (((struct lwan_strbuf *)(s))->used)
#define lwan_strbuf_get_buffer(s) (((struct lwan_strbuf *)(s))->value.buffer)

#include "ringbuffer.h"

#define FOR_EACH_LEXEME(X)                                                     \
