};

#undef GENERATE_ENUM
#undef GENERATE_ARRAY_ITEM

struct lexeme {
    enum lexeme_type type;
    struct {
        const char *value;
        size_t len;
    } value;
};

DEFINE_RING_BUFFER_TYPE(lexeme_ring_buffer, struct lexeme, 4)
DEFINE_RING_BUFFER_TYPE(config_ring_buffer, struct config_line, 4)

struct lexer {
    void *(*state)(struct lexer *);
    const char *start, *pos, *end;
    struct lexeme_ring_buffer buffer;
    int cur_line;
};

struct parser {
    void *(*state)(struct parser *);
    struct lexer lexer;
    struct lexeme_ring_buffer buffer;
    struct config_ring_buffer items;
    struct lwan_strbuf strbuf;
};

struct config {
    struct parser parser;
    char *error_message;
    struct {
        void *addr;
        size_t sz;
    } mapped;
};

enum config_line_type {
    CONFIG_LINE_TYPE_LINE,
    CONFIG_LINE_TYPE_SECTION,
    CONFIG_LINE_TYPE_SECTION_END
};

struct config_line {
    char *key;
    char *value;
    enum config_line_type type;
};

static bool lexeme_buffer_consume(struct lexeme_ring_buffer *buf,
    struct lexeme **lexeme)
{
    if (lexeme_ring_buffer_empty(buf))
        return false;
    *lexeme = lexeme_ring_buffer_get_ptr(buf);
    return true;
}

static bool lexeme_buffer_emit(struct lexeme_ring_buffer *buf,
    struct lexeme *lexeme)
{
    if (lexeme_ring_buffer_full(buf))
        return false;
    lexeme_ring_buffer_put(buf, lexeme);
    return true;
}

static void emit_lexeme(struct lexer *lexer, struct lexeme *lexeme)
{
    if (!lexeme_buffer_emit(&lexer->buffer, lexeme))
        return;
    lexer->start = lexer->pos;
}

static void emit(struct lexer *lexer, enum lexeme_type type)
{
    struct lexeme lexeme = {
        .type = type,
        .value = {
            .value = lexer->start,
            .len = (size_t)(lexer->pos - lexer->start)
        }
    };
    emit_lexeme(lexer, &lexeme);
}

static int next(struct lexer *lexer)
{
    if (lexer->pos >= lexer->end) {
        lexer->pos = lexer->end + 1;
        return '\0';
    }
    int r = *lexer->pos;
    lexer->pos++;
    if (r == '\n')
        lexer->cur_line++;
    return r;
}

static void ignore(struct lexer *lexer)
{
    lexer->start = lexer->pos;
}

static void advance_n(struct lexer *lexer, size_t n)
{
    lexer->pos += n;
    ignore(lexer);
}

static void backup(struct lexer *lexer)
{
    lexer->pos--;
    if (*lexer->pos == '\n')
        lexer->cur_line--;
}

static int peek(struct lexer *lexer)
{
    int chr = next(lexer);
    backup(lexer);
    return chr;
}

static void *lex_config(struct lexer *lexer);
static void *lex_variable(struct lexer *lexer);

static bool isstring(int chr)
{
    return chr && !isspace(chr) && chr != '=' && chr != '#';
}

static void *lex_string(struct lexer *lexer)
{
    int chr;
    do {
        chr = next(lexer);
        if (chr == '$' && peek(lexer) == '{') {
            backup(lexer);
            emit(lexer, LEXEME_STRING);
            advance_n(lexer, strlen("{"));
            return lex_variable;
        }
    } while (isstring(chr));
    backup(lexer);
    emit(lexer, LEXEME_STRING);
    return lex_config;
}

static void *lex_error(struct lexer *lexer, const char *msg)
{
    struct lexeme lexeme = {
        .type = LEXEME_ERROR,
        .value = {
            .value = msg,
            .len = strlen(msg)
        }
    };
    emit_lexeme(lexer, &lexeme);
    return NULL;
}

static void *lex_multiline_string(struct lexer *lexer)
{
    char *end = (peek(lexer) == '"') ? "\"\"\"" : "'''";

    advance_n(lexer, strlen("'''") - 1);

    do {
        if (!strncmp(lexer->pos, end, 3)) {
            emit(lexer, LEXEME_STRING);
            lexer->pos += 3;
            return lex_config;
        }
    } while (next(lexer) != '\0');

    return lex_error(lexer, "EOF while scanning multiline string");
}

static bool isvariable(int chr)
{
    return isalpha(chr) || chr == '_';
}

static void *lex_variable_default(struct lexer *lexer)
{
    while (next(lexer) != '}')
        ;
    backup(lexer);
    emit(lexer, LEXEME_STRING);
    advance_n(lexer, strlen("}"));
    return lex_config;
}

static void *lex_variable(struct lexer *lexer)
{
    int chr;
    advance_n(lexer, strlen("${") - 1);
    do {
        chr = next(lexer);
        if (chr == ':') {
            backup(lexer);
            emit(lexer, LEXEME_VARIABLE_DEFAULT);
            advance_n(lexer, strlen(":"));
            return lex_variable_default;
        }
        if (chr == '}') {
            backup(lexer);
            emit(lexer, LEXEME_VARIABLE);
            advance_n(lexer, strlen("}"));
            return lex_config;
        }
    } while (isvariable(chr));
    return lex_error(lexer, "EOF while scanning for end of variable");
}

static bool iscomment(int chr)
{
    return chr != '\0' && chr != '\n';
}

static void *lex_comment(struct lexer *lexer)
{
    while (iscomment(next(lexer)))
        ;
    backup(lexer);
    return lex_config;
}

static void *lex_config(struct lexer *lexer)
{
    while (true) {
        int chr = next(lexer);
        if (chr == '\0')
            break;
        if (chr == '\n') {
            emit(lexer, LEXEME_LINEFEED);
            return lex_config;
        }
        if (isspace(chr)) {
            ignore(lexer);
            continue;
        }
        if (chr == '{') {
            emit(lexer, LEXEME_OPEN_BRACKET);
            return lex_config;
        }
        if (chr == '}') {
            emit(lexer, LEXEME_CLOSE_BRACKET);
            return lex_config;
        }
        if (chr == '=') {
            emit(lexer, LEXEME_EQUAL);
            return lex_config;
        }
        if (chr == '#')
            return lex_comment;
        if (chr == '\'' && !strncmp(lexer->pos, "''", 2))
            return lex_multiline_string;
        if (chr == '"' && !strncmp(lexer->pos, "\"\"", 2))
            return lex_multiline_string;
        if (chr == '$' && peek(lexer) == '{')
            return lex_variable;
        if (isstring(chr))
            return lex_string;
        return lex_error(lexer, "Invalid character");
    }
    emit(lexer, LEXEME_LINEFEED);
    emit(lexer, LEXEME_EOF);
    return NULL;
}

static bool lex_next(struct lexer *lexer, struct lexeme **lexeme)
{
    while (lexer->state) {
        if (lexeme_buffer_consume(&lexer->buffer, lexeme))
            return true;
        lexer->state = lexer->state(lexer);
    }
    return lexeme_buffer_consume(&lexer->buffer, lexeme);
}

static void *parse_config(struct parser *parser);

static void *parse_key_value(struct parser *parser)
{
    struct config_line line = {.type = CONFIG_LINE_TYPE_LINE};
    struct lexeme *lexeme;
    size_t key_size;

    while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
        lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
                               lexeme->value.len);
        if (!lexeme_ring_buffer_empty(&parser->buffer))
            lwan_strbuf_append_char(&parser->strbuf, '_');
    }
    key_size = lwan_strbuf_get_length(&parser->strbuf);
    lwan_strbuf_append_char(&parser->strbuf, '\0');

    while (lex_next(&parser->lexer, &lexeme)) {
        switch (lexeme->type) {
        case LEXEME_VARIABLE_DEFAULT:
        case LEXEME_VARIABLE:
        case LEXEME_EQUAL:
            lwan_strbuf_append_char(&parser->strbuf, '=');
            break;
        case LEXEME_STRING:
            lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value,
                                   lexeme->value.len);
            break;
        case LEXEME_CLOSE_BRACKET:
            backup(&parser->lexer);
        case LEXEME_LINEFEED:
            line.key = lwan_strbuf_get_buffer(&parser->strbuf);
            line.value = line.key + key_size + 1;
            if (!config_buffer_emit(&parser->items, &line))
                return NULL;
            return parse_config;
        default:
            return NULL;
        }
    }
    return NULL;
}

static void *parse_section(struct parser *parser)
{
    struct lexeme *lexeme;
    size_t name_len;

    if (!lexeme_buffer_consume(&parser->buffer, &lexeme))
        return NULL;

    lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
    name_len = lexeme->value.len;
    lwan_strbuf_append_char(&parser->strbuf, '\0');

    while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
        lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
        if (!lexeme_ring_buffer_empty(&parser->buffer))
            lwan_strbuf_append_char(&parser->strbuf, ' ');
    }

    struct config_line line = {
        .type = CONFIG_LINE_TYPE_SECTION,
        .key = lwan_strbuf_get_buffer(&parser->strbuf),
        .value = lwan_strbuf_get_buffer(&parser->strbuf) + name_len + 1
    };
    if (!config_buffer_emit(&parser->items, &line))
        return NULL;
    return parse_config;
}

static void *parse_section_shorthand(struct parser *parser)
{
    void *next_state = parse_section(parser);
    if (next_state) {
        struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
        if (!config_buffer_emit(&parser->items, &line))
            return NULL;
        return next_state;
    }
    return NULL;
}

static void *parse_config(struct parser *parser)
{
    struct lexeme *lexeme;
    if (!lex_next(&parser->lexer, &lexeme))
        return NULL;
    switch (lexeme->type) {
    case LEXEME_EQUAL:
        return parse_key_value;
    case LEXEME_OPEN_BRACKET:
        return parse_section;
    case LEXEME_LINEFEED:
        if (!lexeme_ring_buffer_empty(&parser->buffer))
            return parse_section_shorthand;
        return parse_config;
    case LEXEME_STRING:
        lexeme_buffer_emit(&parser->buffer, lexeme);
        return parse_config;
    case LEXEME_CLOSE_BRACKET: {
        struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
        config_buffer_emit(&parser->items, &line);
        return parse_config;
    }
    case LEXEME_EOF:
        return NULL;
    default:
        return NULL;
    }
}

static bool parser_next(struct parser *parser, struct config_line **line)
{
    while (parser->state) {
        if (config_buffer_consume(&parser->items, line))
            return true;
        lwan_strbuf_reset(&parser->strbuf);
        parser->state = parser->state(parser);
    }
    return config_buffer_consume(&parser->items, line);
}

static struct config *config_init_data(struct config *config,
                                       void *data, size_t len)
{
    config->parser = (struct parser) {
        .state = parse_config,
        .lexer = {
            .state = lex_config,
            .pos = data,
            .start = data,
            .end = (char *)data + len,
            .cur_line = 1,
        }
    };
    config->error_message = NULL;
    lwan_strbuf_init(&config->parser.strbuf);
    config_ring_buffer_init(&config->parser.items);
    lexeme_ring_buffer_init(&config->parser.buffer);
    return config;
}

static bool config_buffer_consume(struct config_ring_buffer *buf,
    struct config_line **line)
{
    if (config_ring_buffer_empty(buf))
        return false;
    *line = config_ring_buffer_get_ptr(buf);
    return true;
}

static bool config_buffer_emit(struct config_ring_buffer *buf,
    struct config_line *line)
{
    if (config_ring_buffer_full(buf))
        return false;
    config_ring_buffer_put(buf, line);
    return true;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *data = malloc(sz + 1);
    fread(data, 1, sz, f);
    fclose(f);

    struct config config;
    config_init_data(&config, data, sz);

    struct config_line *line;
    while (parser_next(&config.parser, &line)) {
        /* consume all */
    }

    printf("Done (no crash)\n");
    free(data);
    return 0;
}
