    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = malloc((size_t)sz + 1);
    fread(data, 1, (size_t)sz, f);
    fclose(f);
    struct config config;
    config_init_data(&config, data, (size_t)sz);
    struct config_line *line;
    while (parser_next(&config.parser, &line)) {}
    printf("Done (no crash)\n");
    free(data);
    return 0;
}
