static void *parse_section(struct parser *parser) {
    struct lexeme *lexeme;
    size_t name_len;
    if (!lexeme_buffer_consume(&parser->buffer, &lexeme)) return NULL;
    lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
    name_len = lexeme->value.len;
    lwan_strbuf_append_char(&parser->strbuf, '\0');
    while (lexeme_buffer_consume(&parser->buffer, &lexeme)) {
        lwan_strbuf_append_str(&parser->strbuf, lexeme->value.value, lexeme->value.len);
        if (!lexeme_ring_buffer_empty(&parser->buffer)) lwan_strbuf_append_char(&parser->strbuf, ' ');
    }
    struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION, .key = lwan_strbuf_get_buffer(&parser->strbuf), .value = lwan_strbuf_get_buffer(&parser->strbuf) + name_len + 1 };
    if (!config_buffer_emit(&parser->items, &line)) return NULL;
    return parse_config;
}

static void *parse_section_shorthand(struct parser *parser) {
    void *next_state = parse_section(parser);
    if (next_state) {
        struct config_line line = { .type = CONFIG_LINE_TYPE_SECTION_END };
        if (!config_buffer_emit(&parser->items, &line)) return NULL;
        return next_state;
    }
    return NULL;
}

static void *parse_config(struct parser *parser) {
    struct lexeme *lexeme;
    if (!lex_next(&parser->lexer, &lexeme)) return NULL;
    switch (lexeme->type) {
    case LEXEME_EQUAL: return parse_key_value;
    case LEXEME_OPEN_BRACKET: return parse_section;
    case LEXEME_LINEFEED:
